/**
 * Real mint and metadata accounts captured from mainnet.
 *
 * Both standards are represented because both are live: pump.fun mints are
 * Token-2022 with metadata inline, while older SPL tokens keep it in a separate
 * Metaplex account. Assuming only one of those exists is the mistake this
 * fixture set is here to prevent.
 */

export interface AccountFixture {
  readonly mint: string;
  readonly owner: string;
  readonly base64: string;
  readonly address?: string;
}

/** A Token-2022 pump.fun mint carrying the TokenMetadata extension. */
export const TOKEN_2022_MINT: AccountFixture = {
  "mint": "3SPyj7fHQ6TKGR5Agua1gPdCnb2oWHF8Zi8bY33bpump",
  "owner": "TokenzQdBNbLqP5VEhdkAS6EPFLC1PHnBqCXEpPxuEb",
  "base64": ""
};

/** A second one, to catch anything that only works for a single string length. */
export const TOKEN_2022_MINT_B: AccountFixture = {
  "mint": "J5reXJehdCV86HPHg2ewbeGYfMkxQT2YmLcg4DVfpump",
  "owner": "TokenzQdBNbLqP5VEhdkAS6EPFLC1PHnBqCXEpPxuEb",
  "base64": ""
};

/** A classic Metaplex metadata account (USDC). */
export const METAPLEX_METADATA: AccountFixture = {
  "mint": "EPjFWdd5AufqSSqeM2qN1xzybapC8G4wEGGkZwyTDt1v",
  "address": "5x38Kp4hvdomTCnCrAny4UtMUt5rQBdB6px2K1Ui45Wq",
  "owner": "metaqbxxUerdq28cj1RbAWkYQm3ybzjb6a8bt518x1s",
  "base64": ""
};

export function bytes(base64: string): Uint8Array {
  return Uint8Array.from(Buffer.from(base64, 'base64'));
}
